        group post by post.BlogId into blogPosts
        select new
        {
            BlogId = blogPosts.Key,
            TotalViews = blogPosts.Sum(blogPost => (long)blogPost.Views)
        };

    var totals = await query.ToListAsync(cancellationToken);

    return totals.ToDictionary(total => total.BlogId, total => total.TotalViews);
